import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t,o as _,c as e,a3 as o}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/48-崇礼第三十七.md","filePath":"books/yan-tie-lun/48-崇礼第三十七.md","lastUpdated":1794316978000}'),n={name:"books/yan-tie-lun/48-崇礼第三十七.md"};function r(s,a,i,l,d,c){return _(),e("div",null,[...a[0]||(a[0]=[o('<p>崇礼第三十七 【题解】</p><p>本篇所论有两个要点：第一个要点是如何看待接待蛮夷邦国君主的礼仪。大夫认为，朝廷在接待蛮夷时陈列旌旗车马和珍奇野兽，是为了展示中国威武，怀柔远方异族，宣明圣主盛德：“列羽旄，陈戎马，所以示威武；奇虫珍怪，所以示怀广远、明盛德，远国莫不至。”贤良指出，中国应该用“王者崇礼施德，上仁义而贱怪力”的方式来感化远方异族，而不是炫耀玩好、奇兽和游戏。第二个要点是如何看待贤才在国家的作用。大夫以晏婴相齐为例，说明贤人对国家损益关系不大。贤良则认为，贤才所在国重，所去国轻，贤才关系到国家的生死存亡。</p><p>大夫曰：“饰几杖[(1)]，修樽俎[(2)]，为宾，非为主也。炫耀奇怪[(3)]，所以陈四夷[(4)]，非为民也。夫家人有客，尚有倡优奇变之乐[(5)]，而况县官乎？故列羽旄[(6)]，陈戎马[(7)]，所以示威武[(8)]；奇虫珍怪[(9)]，所以示怀广远、明盛德[(10)]，远国莫不至也。”</p><p>【注释】</p><p>[(1)]饰：装饰。几：几案，摆在座前的小桌子，用于凭靠。杖：手杖。为老人预备几杖，是中国古代优待老人的重要礼仪。《礼记·曲礼上》：“大夫七十而致事，若不得谢，则必赐之几杖。”</p><p>[(2)]修：修饰。樽（zūn）：酒杯。俎（zǔ）：古代祭祀或宴会时用来盛牲的礼器。</p><p>[(3)]奇怪：奇珍异宝。</p><p>[(4)]陈：陈列，展示。四夷：东夷，南蛮，西戎，北狄。</p><p>[(5)]倡优：古代歌舞杂技艺人。奇变：奇异变化。</p><p>[(6)]羽旄：用鸟羽和旄牛尾装饰的旗帜。羽，鸟羽。旄，旄牛尾。</p><p>[(7)]戎马：兵车战马。</p><p>[(8)]所以示威武：“所”字原无，据王利器说校补。</p><p>[(9)]奇虫：珍奇野兽。</p><p>[(10)]所以示怀广远、明盛德：怀广远，怀柔边远异族。“盛”字原无，据陈遵默说补正。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“修饰几案和手杖，准备酒杯和盛牲器皿，这是为了接待宾客，而不是为了主人。炫耀地展示奇珍异宝，是为了让四方蛮夷开眼界，并不是为了本国民众。老百姓家里来了贵客，尚且有歌舞杂技奇妙变化的娱乐，何况是朝廷呢？因此陈列用鸟羽、旄牛尾装饰的旌旗，摆开兵车和战马，是用来展示大国的威武，珍奇野兽，瑰宝奇物，是用来怀柔远方异族、宣明圣主盛德，使远方邦国都来朝归附。”</p><p>贤良曰：“王者崇礼施德[(1)]，上仁义而贱怪力[(2)]，故圣人绝而不言[(3)]。孔子曰：‘言忠信，行笃敬，虽蛮、貊之邦，不可弃也。’[(4)]今万方绝国之君奉贽献者[(5)]，怀天子之盛德，而欲观中国之礼仪，故设明堂、辟雍以示之[(6)]，扬干戚、昭《雅》、《颂》以风之[(7)]。今乃以玩好不用之器[(8)]，奇虫不畜之兽[(9)]，角抵诸戏[(10)]，炫耀之物陈夸之，殆与周公之待远方殊[(11)]。昔周公处谦以卑士，执礼以治天下[(12)]，辞越裳之贽[(13)]，见恭让之礼也[(14)]；既[(15)]，与入文王之庙，是见大孝之礼也。目睹威仪干戚之容，耳听清歌《雅》、《颂》之声[(16)]，心充至德，欣然以归，此四夷所以慕义内附，非重译狄鞮来观猛兽熊罴也[(17)]。夫犀象兕虎，南夷之所多也；骡驴馲驼[(18)]，北狄之常畜也。中国所鲜[(19)]，外国贱之，南越以孔雀珥门户[(20)]，昆山之旁[(21)]，以玉璞抵乌鹊[(22)]。今贵人之所贱，珍人之所饶，非所以厚中国，明盛德也。隋、和[(23)]，世之名宝也[(24)]，而不能安危存亡。故喻德示威，惟贤臣良相，不在犬马珍怪。是以圣王以贤为宝，不以珠玉为宝。昔晏子修之樽俎之间[(25)]，而折冲乎千里[(26)]；不能者，虽隋、和满箧[(27)]，无益于存亡。”</p><p>【注释】</p><p>[(1)]崇礼：崇尚礼仪。施德：施行恩德。</p><p>[(2)]上：同“尚”，崇尚。贱怪力：轻视怪异和暴力。</p><p>[(3)]圣人绝而不言：《论语·述而》：“子不语怪、力、乱、神。”圣人，指孔子。</p><p>[(4)]言忠信，行笃敬，虽蛮、貊之邦，不可弃也：见于《论语·卫灵公》，但最后一句不同。忠信，忠诚老实。笃敬，忠厚严肃。蛮、貊之邦，蛮荒落后的地方。</p><p>[(5)]绝国：绝远之国。贽（zhì）：见面礼，古代不同级别的人有不同的见面礼。</p><p>[(6)]明堂：古代天子举行祭祀、朝会、庆典、选士的地方。辟雍：古代天子所设立的大学，建筑呈圆形，四周有水池，前门外有便桥。</p><p>[(7)]扬：挥舞。干：盾。戚：斧。扬干戚为武舞。昭：明，此处指演唱。风：风化，感化。</p><p>[(8)]今乃以玩好不用之器：于是把仅供赏玩而不实用的器物。按，“乃”下原无“以”字，据王利器说校补。</p><p>[(9)]不畜：不宜蓄养。畜，通“蓄”。</p><p>[(10)]角抵：古代一种角力游戏，类似于现代的摔跤、拳击。</p><p>[(11)]殊：不同。</p><p>[(12)]执礼以治天下：此句原作“执礼以治下天下”，据王利器说删前一个“下”字。</p><p>[(13)]辞越裳之贽：传说越裳氏以珍禽白雉作为见面礼来见周成王，周公以德行不够而予以谢绝。</p><p>[(14)]也：此字原无，据王先谦说校补。见：同“现”。</p><p>[(15)]既：指见面礼完毕。</p><p>[(16)]清：《群书治要》作“升”。</p><p>[(17)]重译：经过几重翻译。狄鞮（dī）：西方少数民族对翻译官的称呼。罴（pí）：熊的一种，也叫马熊或人熊。</p><p>[(18)]馲（tuō）驼：骆驼。</p><p>[(19)]鲜：稀少。</p><p>[(20)]珥（ěr）：插于耳旁。</p><p>[(21)]昆山：山名，即昆仑山，为产玉之地。</p><p>[(22)]玉璞：玉石。抵：投掷。</p><p>[(23)]隋：隋侯之珠。传说隋侯遇到受伤的大蛇，命人救治，后来大蛇衔珠来报答隋侯。后人将这颗珍珠称为“隋侯之珠”。和：和氏之璧。楚人卞和得到一块玉璞，他献给楚厉王，厉王认为是欺骗，砍掉他的左脚。楚武王即位后，卞和又将玉璞献上，武王又认为他是欺骗，砍掉他的右脚。楚文王即位后，卞和怀抱玉璞在楚山之下痛哭三日三夜，楚文王派玉人治璞而得奇宝，于是将这块玉璧命名为“和氏之璧”。隋侯之珠、和氏之璧由此成为中国古代绝世珍宝的代称。</p><p>[(24)]世之名宝也：“世”字原无，据王先谦说校补。</p><p>[(25)]晏子：春秋后期齐国贤相晏婴。修之樽俎之间：指在酒宴之上注重礼仪。</p><p>[(26)]折冲：使战车折回，指击退敌军。冲，战车。</p><p>[(27)]箧（qiè）：小箱子。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“君王崇尚礼仪，普施恩德，推崇仁义道德，轻视怪异暴力，因此圣人从来不谈论怪异、暴力、叛乱和神灵。孔子说：‘言谈忠诚老实，行为忠厚严肃，即使是在蛮荒落后地区，也不可丢弃这些品质。’如今四面八方绝远邦国的君主都来汉朝奉献见面礼，感怀天子的盛德，想来观看中国的礼仪，因此朝廷设立用来朝觐的明堂、用来讲学教化的辟雍，让那些远方君主观看，宫廷艺人跳起手执盾牌大斧的武舞、演唱《雅》、《颂》歌诗来感化他们。如今朝廷却以好玩而不实用的器物，家庭不蓄养的奇兽，以及角抵等游戏，用这些炫耀之事物向人展示，这恐怕与当年周公接待远方诸侯的方式不一样。从前周公以谦卑的态度对待贤士，用周礼来治理天下，他谢绝了越裳国奉献的白雉见面礼，以此让越裳国看到什么是恭让之礼；见面礼完毕之后，周公与越裳国君参拜文王之庙，以此让越裳国君看到什么是大孝之礼。越裳国君亲眼目睹了象征威仪、手执盾斧的武舞，亲耳聆听演唱《雅》、《颂》的歌声，心里充满了高尚的道德，高兴地回到自己邦国，这就是四方蛮夷仰慕仁义向内归附中国的原因，他们并不是通过几重翻译来观赏中国的猛兽熊罴。犀牛、大象、老虎，是南方蛮夷常见的野兽；骡子、毛驴、骆驼，是北方夷狄常见的牲畜。中国所罕见的野兽牲畜，外国却并不重视，南越人用珍贵的孔雀羽毛装饰门户，在产玉的昆山之旁，人们用宝贵的玉石来投掷乌鹊。如今朝廷把别人所轻视的东西看得很贵重，把别人多有的东西视为珍宝，这不是提高中国地位，宣明皇上盛德的好方法。隋侯之珠、和氏之璧，是世上公认的著名宝玉，但它们却不能使国家转危为安，更不能使即将灭亡的国家生存下去。因此，宣传恩德，展示威武，只有依靠贤臣良相，而不在于犬马珍宝。所以，圣王以贤才为国家珍宝，而不是以珠玉为宝。从前齐国贤相晏婴在酒宴之上展示礼仪，使千里之外敌军的战车折回；如果不能做到以礼服人，即使隋侯之珠、和氏之璧装满箱子，对国家存亡也是没有益处的。”</p><p>大夫曰：“晏子相齐三君[(1)]，崔、庆无道[(2)]，劫其君[(3)]，乱其国，灵公国围[(4)]；庄公弑死；景公之时，晋人来攻，取垂都[(5)]，举临菑[(6)]，边邑削，城郭焚，宫室隳[(7)]，宝器尽，何冲之所能折乎？由此观之：贤良所言，贤人为宝，则损益无轻重也。”</p><p>【注释】</p><p>[(1)]相齐三君：晏婴先后辅佐齐国灵公、庄公、景公三位君主。</p><p>[(2)]崔、庆无道：齐庄公与崔杼之妻通奸，崔杼杀死齐庄公。后来崔杼家庭发生内讧，庆封乘机围攻崔氏，崔杼上吊自杀。崔，齐国大夫崔杼。庆，齐国大夫庆封。</p><p>[(3)]劫其君：指崔杼劫持齐庄公。</p><p>[(4)]灵公国围：《史记·齐太公世家》：“二十七年，晋使中行子伐齐。齐师败，灵公走入临菑。晏婴止灵公，灵公弗从。曰：‘君亦无勇矣！’晋兵遂围临菑，临菑守不敢出，晋焚郭中而去。”灵公被围之事发生在公元前555年。国，原误作“同”，据张敦仁、杨沂孙说校改。</p><p>[(5)]垂都：《战国策·魏策》载“垂都焚”，垂都为魏国邑名，可能是桑弘羊记忆有误。一说，垂都，边境的都市。</p><p>[(6)]举：攻占。临菑：齐国都城。按，史籍未载齐景公时期晋人攻陷齐国首都之事，不知桑弘羊此说有何依据。</p><p>[(7)]隳（huī）：毁坏。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“晏子先后辅佐齐灵公、齐庄公、齐景公三代君主，崔杼、庆封不遵为臣之道，劫持君主，扰乱齐国，齐灵公时期齐国被围；齐庄公被崔杼杀死；齐景公时期，晋人前来进攻，夺取垂都，攻占齐国首都临菑，齐国边邑被削，城郭被焚烧，宫室被毁坏，珍宝被抢光，哪里有什么战车折回的事呢？由此看来：贤良说“贤人为国家珍宝”，其实贤人对国家的损益无足轻重。”</p><p>贤良曰：“管仲去鲁入齐[(1)]，齐霸鲁削，非持其众而归齐也[(2)]。伍子胥挟弓干阖闾[(3)]，破楚入郢[(4)]，非负其兵而适吴也。故贤者所在国重，所去国轻。楚有子玉得臣[(5)]，文公侧席[(6)]；虞有宫之奇[(7)]，晋献不寐[(8)]。夫贤臣所在[(9)]，辟除开塞者亦远矣[(10)]。故《春秋》曰：‘山有虎豹，葵藿为之不采；国有贤士，边境为之不害’也[(11)]。”</p><p>【注释】</p><p>[(1)]管仲：春秋前期齐国政治家，辅佐齐桓公开创霸主政治。去鲁入齐：齐襄公晚年，为了逃避齐国政治动乱，管仲奉公子纠奔鲁，鲍叔奉公子小白奔莒。齐襄公死后，公子小白抢先回国即位，是为齐桓公。齐国致书鲁国，要鲁国杀掉公子纠，送回管仲。鲁国因畏齐而照办。</p><p>[(2)]持：原作“恃”，据王利器说校改。</p><p>[(3)]伍子胥：楚国大夫伍奢之子。伍奢与大儿子伍尚被楚平王无辜杀害，伍子胥历尽千辛万苦，辗转奔吴，最终得借吴国之力报父兄之仇。挟弓：楚平王派人抓捕伍子胥，伍子胥张弓搭箭，对准使者，使者不敢近前，伍子胥因此得以逃脱。干：求。阖闾：吴王。</p><p>[(4)]破楚入郢：吴王阖闾九年，伍子胥率吴兵攻入楚国郢都。</p><p>[(5)]子玉得臣：春秋楚国令尹，成氏，名得臣，字子玉。他是晋文公重耳争霸的主要对手，因在晋楚城濮之战中失败而自杀。</p><p>[(6)]文公：晋文公重耳，是继齐桓公之后的春秋霸主。侧席：侧身而坐，表示不安。</p><p>[(7)]宫之奇：春秋时期虞国贤臣，曾力谏虞君不要借道给晋国，虞君不听，最后被晋国所灭。《春秋繁露·服制象》：“虞有宫之奇，晋献不寐。”</p><p>[(8)]晋献：晋献公，春秋时期晋国君主，姬姓，名诡诸，曾采用荀息假道伐虢之计吞并虞、虢。</p><p>[(9)]贤臣所在：“臣”上原脱“贤”字，据王先谦说校补。</p><p>[(10)]辟除：扫除障碍。开塞：开疆拓土。</p><p>[(11)]山有虎豹，葵藿为之不采；国有贤士，边境为之不害：此处所引文字不见于今本《春秋》，可能是出自汉代《春秋》传记。葵藿，两种野菜。采，采摘。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“管仲离开鲁国进入齐国，导致齐国称霸鲁国削弱，这并不是管仲劫持鲁国民众归于齐国。伍子胥挟持弓箭求助于吴王阖闾，率领吴师攻破楚国进入郢都，他没有扛着兵器跑到吴国。因此，贤才所在国家的地位重要，贤才所离开的国家地位轻微。楚国有令尹子玉得臣，晋文公为之侧席而坐；虞国有贤才宫之奇，晋献公为之睡不着。凡是贤臣所在之处，野心家要想扫除障碍、开疆拓土，这些目标都变得遥远了。因此《春秋》传记说：‘山上有虎豹，葵藿野菜无人敢去采摘；国家有贤士，边境不会遭受侵害。’”</p>',77)])])}const g=t(n,[["render",r]]);export{f as __pageData,g as default};
